import java.util.*;

class Solution {
    public List<Integer> maxSlidingWindow(int[] readings, int k) {
        Deque<Integer> dq = new ArrayDeque<>(); // indices, readings decreasing from front to back
        List<Integer> res = new ArrayList<>();
        for (int i = 0; i < readings.length; i++) {
            if (!dq.isEmpty() && dq.peekFirst() <= i - k) dq.pollFirst();      // slid out of the frame
            while (!dq.isEmpty() && readings[dq.peekLast()] <= readings[i]) dq.pollLast(); // can never be the peak
            dq.offerLast(i);
            if (i >= k - 1) res.add(readings[dq.peekFirst()]);
        }
        return res;
    }
}

