class Solution:
    def maxSlidingWindow(self, readings: List[int], k: int) -> List[int]:
        dq = deque(); out = []
        for i, x in enumerate(readings):
            while dq and readings[dq[-1]] <= x: dq.pop()
            dq.append(i)
            if dq[0] <= i - k: dq.popleft()
            if i >= k - 1: out.append(readings[dq[0]])
        return out

