function maxSlidingWindow(a, k) {
  const out = [];
  for (let i = 0; i + k <= a.length; i++) { let m = -Infinity; for (let j = i; j < i + k; j++) m = Math.max(m, a[j]); out.push(m); }
  return out;
}
